// Obtengo el primer item (ajusta si procesás en lote)
const item   = $input.all()[0];
const source = $input.first().json.message.content
/**

 * Limpia signos de apertura (¿ ¡) y
 * colapsa saltos de línea dobles a simples \n
 */
function cleanString (str) {
  if (typeof str !== 'string') return str;

  return str
    .replace(/[¿¡]/g, '')   // quita signos
    .replace(/\n{2,}/g, '\n'); // reemplaza \n\n (o más) por \n
}

const cleanedContent = {};
for (const key in source) {
  cleanedContent[key] = cleanString(source[key]);
}

return [{
  json: {
    ...item.json,
    message: {
      ...item.json.message,
      content: cleanedContent,
    },
  },
}];

const out = [];

for (const item of items) {
  // 1️⃣  Parseamos 'productos' a array real
  let lista = item.json.productos;
  if (typeof lista === "string") {
    try { lista = JSON.parse(lista); } catch { lista = [ lista ]; }
  }
  if (!Array.isArray(lista) || lista.length === 0) {
    return {}
  }

  // 2️⃣  Armamos el bloque OR( SEARCH(...) > 0, … )
  const searchParts = lista
    .map(p => `SEARCH("${p.toLowerCase()}", LOWER({productos})) > 0`)
    .join(",\n    ");     // salto de línea solo para legibilidad

  // 3️⃣  Fórmula final AND( subcategoria, OR(...) )
  const formula = `AND(
    {subcategoria} = "${item.json.subcategoria}",
    OR(
      ${searchParts}
    )
  )`;

  // 4️⃣  Devolvemos un único item con la fórmula (podrías url-encodearla acá si querés)
  out.push({ json: { filterByFormula: formula } });
}

return out;

