const TZ = 'America/Mexico_City';

// Obtiene día/hora/minuto en la zona horaria de CDMX de forma robusta
function nowInMexicoCity() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: TZ,
    weekday: 'short',
    hour: 'numeric',
    minute: 'numeric',
    hour12: false,
  }).formatToParts(new Date())
    .reduce((acc, p) => (acc[p.type] = p.value, acc), {});

  const weekday = parts.weekday;              // 'Mon', 'Tue', ... 'Sat', 'Sun'
  const hour = parseInt(parts.hour, 10);      // 0..23
  const minute = parseInt(parts.minute, 10);  // 0..59
  const minutesOfDay = hour * 60 + minute;    // 0..1439

  return { weekday, minutesOfDay };
}

function isWithinBusinessHoursMx({ weekday, minutesOfDay }) {
  const WEEKDAYS = new Set(['Mon', 'Tue', 'Wed', 'Thu', 'Fri']);
  const SATURDAY = 'Sat';

  const OPEN_MIN = 9 * 60;   // 09:00 => 540
  const CLOSE_WD = 18 * 60;  // 18:00 => 1080 (exclusivo)
  const CLOSE_SA = 14 * 60;  // 14:00 => 840  (exclusivo)

  if (WEEKDAYS.has(weekday)) {
    return minutesOfDay >= OPEN_MIN && minutesOfDay < CLOSE_WD;
  }
  if (weekday === SATURDAY) {
    return minutesOfDay >= OPEN_MIN && minutesOfDay < CLOSE_SA;
  }
  return false; // Domingo
