// n8n Code node (JavaScript)
// Lee $input.first().json.data (puede venir como string JSON o como objeto)
// y extrae status_id en una variable: statusId

const raw = $input.first().json.data;

let dataObj;
if (typeof raw === 'string') {
  try {
    dataObj = JSON.parse(raw);
  } catch (e) {
    throw new Error('No se pudo parsear $input.first().json.data como JSON: ' + e.message);
  }
} else {
  dataObj = raw;
}

const statusId = dataObj?.status_id;

if (statusId === undefined || statusId === null) {
  throw new Error('status_id no existe en data');
}

// Devolvemos el valor en un item, para que quede accesible como {{$json.status_id}}
return [
  {
    json: {
      status_id: statusId,
    },
  },
];

const out = [];

for (const item of items) {
  // 1️⃣  Parseamos 'productos' a array real
  let lista = item.json.productos;
  if (typeof lista === "string") {
    try { lista = JSON.parse(lista); } catch { lista = [ lista ]; }
  }
  if (!Array.isArray(lista) || lista.length === 0) {
    return {}
  }

  // 2️⃣  Armamos el bloque OR( SEARCH(...) > 0, … )
  const searchParts = lista
    .map(p => `SEARCH("${p.toLowerCase()}", LOWER({productos})) > 0`)
    .join(",\n    ");     // salto de línea solo para legibilidad

  // 3️⃣  Fórmula final AND( subcategoria, OR(...) )
  const formula = `AND(
    {subcategoria} = "${item.json.subcategoria}",
    OR(
      ${searchParts}
    )
  )`;

  // 4️⃣  Devolvemos un único item con la fórmula (podrías url-encodearla acá si querés)
  out.push({ json: { filterByFormula: formula } });
}

return out;

